    "Chacoalhar": "Shake",
    "Texto do comentário ao lado do nome": "Comment text beside the name",
    "(desligado = embaixo do nome, como sempre foi)": "(off = below the name, the way it has always been)",
    "É o mesmo formato do 💬 Chat ao vivo fixo: o nome e o comentário na mesma linha, com o horário à direita. Vale para a aba Ao vivo, para as colunas e para as outras listas do painel.": "Same layout as the 💬 Fixed live chat: the name and the comment on one line, with the time on the right. Applies to the Live tab, to the columns and to the other lists in the dashboard.",
    "📄 Texto do comentário embaixo do nome (igual ao painel ao vivo)": "📄 Comment text below the name (like the live dashboard)",
    "🔐 O navegador diz \"a conexão com este site não é segura\". Isso é problema?": "🔐 The browser says \"your connection to this site is not secure\". Is that a problem?",
    "Não é problema.": "It is not a problem.",
    "Esse recado aparece em todo endereço que começa com \"http://\" e não quer dizer que alguém esteja bisbilhotando o seu painel.": "That message shows up on every address starting with \"http://\" and it does not mean anyone is snooping on your dashboard.",
    "No seu computador (localhost):": "On your own computer (localhost):",
    "os navegadores tratam o localhost como origem confiável por definição. Esses dados nunca saem da máquina — não passam por cabo, Wi-Fi nem internet. O aviso ali é só o texto padrão do \"http://\".": "browsers treat localhost as a trusted origin by definition. This data never leaves the machine — no cable, no Wi-Fi, no internet. The warning there is just the standard \"http://\" text.",
    "No endereço da sua rede (192.168...):": "On your network address (192.168...):",
    "os dados andam apenas entre o seu computador e o aparelho do seu mod, passando pelo seu roteador. Nada disso vai para a internet.": "the data travels only between your computer and your mod’s device, through your own router. None of it goes to the internet.",
    "Por que o OBS Social não usa \"https\"?": "Why doesn’t OBS Social use \"https\"?",
    "O cadeado do https depende de um certificado, e certificado de verdade só é emitido para um nome de site público, como \"seusite.com.br\". Um endereço caseiro de rede não tem nome público — e nem deveria ter, porque ele não existe fora da sua casa.": "The https padlock depends on a certificate, and a real certificate is only issued for a public site name, like \"yoursite.com\". A home network address has no public name — and shouldn’t have one, because it does not exist outside your house.",
    "E um certificado feito em casa?": "And a home-made certificate?",
    "Seria pior: o navegador passaria a mostrar uma tela vermelha de perigo toda vez, em cada aparelho, e para tirá-la você teria que instalar um arquivo de confiança no sistema — exatamente o tipo de coisa que faz o antivírus apitar. Por isso o OBS Social não faz isso.": "It would be worse: the browser would show a red danger screen every single time, on every device, and to get rid of it you would have to install a trust file into the system — exactly the kind of thing that sets off antivirus alarms. That is why OBS Social does not do it.",
    "O que realmente protege você aqui": "What actually protects you here",
    "é o que está logo abaixo: o programa só aceita conexões da sua própria rede, você escolhe o que a rede pode usar e ainda pode colocar uma senha.": "is what you see right below: the program only accepts connections from your own network, you choose what the network may use, and you can even set a password.",
    "🔟 Mostrar os décimos de segundo no cronômetro (00:05.4)": "🔟 Show tenths of a second on the stopwatch (00:05.4)",
    "🔇 Clique aqui para liberar o som dos alertas": "🔇 Click here to allow the alert sound",
    "🔇 Toque aqui para liberar o som dos alertas": "🔇 Tap here to allow the alert sound",
    "O navegador só toca som depois de um clique na página": "The browser only plays sound after a click on the page",
    "Toque uma vez para o navegador liberar o som": "Tap once so the browser allows sound",
    "Se o navegador disser \"não é seguro\", é só porque o endereço é da sua rede e não da internet — a explicação completa está em ⚙️ Configurações → 🔗 URLs para o OBS.": "If the browser says \"not secure\", it is only because the address belongs to your network and not to the internet — the full explanation is in ⚙️ Settings → 🔗 URLs for OBS.",
