    '🗄️ Mexer nos logs': '🗄️ Manage logs',
    'Assistir ao painel é sempre permitido; o resto só funciona com o seletor ligado. Quem entrar com a senha abaixo ignora os seletores e controla tudo.':
      'Watching the dashboard is always allowed; the rest only works with the switch on. Anyone who enters with the password below bypasses the switches and controls everything.',
    '🔑 Senha de acesso pela rede (opcional) —': '🔑 Network access password (optional) —',
    'Com senha, quem abre o painel pela rede pode entrar com ela e aí controla tudo (os seletores acima valem para quem NÃO entrou). A senha vira um código embaralhado (hash) — nunca fica gravada em texto. Só este computador pode definir, trocar ou remover.':
      'With a password, anyone opening the dashboard over the network can sign in with it and then control everything (the switches above apply to those who did NOT sign in). The password becomes a scrambled code (hash) — it is never stored as text. Only this computer can set, change or remove it.',
