    'Mude a cara deste painel de controle.': 'Change the look of this control panel.',
    '🧲 Organizar o painel — arraste para reordenar (prévia em tempo real)': '🧲 Arrange the dashboard — drag to reorder (live preview)',
    'A prévia abaixo mostra como o painel está ficando; arraste um ícone ou uma aba para a posição que quiser. Se o painel estiver aberto em outra aba, ele muda na hora.':
      'The preview below shows how the dashboard is shaping up; drag an icon or a tab to the position you want. If the dashboard is open in another browser tab, it changes instantly.',
