      'The button above opens your e-mail app with the message ready (the program version goes along, to help investigate). If you prefer, copy the address and send it from wherever you like.',
    'Escreva a sua mensagem primeiro 🙂': 'Write your message first 🙂',
    '— enviado do OBS Social': '— sent from OBS Social',
    'O OBS Social é gratuito e sempre será. Se ele te ajuda nas lives e você quiser retribuir, qualquer valor é bem-vindo — basta apontar a câmera do celular para um dos QR codes. Muito obrigado! 💜':
      'OBS Social is free and always will be. If it helps your streams and you’d like to give back, any amount is welcome — just point your phone camera at one of the QR codes. Thank you so much! 💜',
