    "devolve todas as configurações ao estado original (cores, posições, widgets, idioma, Labs...). É como reinstalar o programa. Sua senha de acesso pela rede é mantida, para você não ficar trancado fora — removê-la é uma opção separada, em 🔗 URLs para o OBS.": "returns every setting to its original state (colors, positions, widgets, language, Labs...). It is like reinstalling the program. Your network access password is kept, so you don’t get locked out — removing it is a separate option, in 🔗 URLs for OBS.",
