    "🖥️ 3440×1440 (ultrawide)": "🖥️ 3440×1440 (ultrawide)",
    "📱 1080×1920 (vertical)": "📱 1080×1920 (portrait)",
    "📱 720×1280 (vertical)": "📱 720×1280 (portrait)",
    "Deixe o OBS Social com a sua cara: cores, imagem de fundo, tamanhos de texto e de ícones, cantos e espaçamento. Isto muda o": "Make OBS Social look like you: colors, background image, text and icon sizes, corners and spacing. This changes the",
    "painel e as configurações": "panel and the settings",
    "— e, com o 🖥️ abaixo ligado, os": "— and, with the 🖥️ below on, the",
    "overlays da live": "stream overlays",
    "vestem o tema junto. O": "wear the theme too. The",
    "(no painel) continua funcionando por cima disto, para aumentar tudo de uma vez.": "(in the panel) keeps working on top of this, to enlarge everything at once.",
    "Vestir também os overlays da live": "Also dress the stream overlays",
    "— ao carregar um tema, o cartão do destaque, o chat fixo e os widgets ganham as cores, os cantos e a fonte dele (o QR mantém o fundo branco, para continuar escaneável)": "— when loading a theme, the highlight card, the pinned chat and the widgets take its colors, corners and font (the QR keeps its white background, to stay scannable)",
    "Acessibilidade": "Accessibility",
    "♿ Acessibilidade": "♿ Accessibility",
    "Recursos para o OBS Social funcionar bem para todo mundo. Cada um tem o seu liga/desliga e vale no": "Features so OBS Social works well for everyone. Each one has its own switch and applies to the",
    "painel e nas configurações": "panel and the settings",
    "na hora, em todos os aparelhos conectados. Os overlays do OBS (o conteúdo que o público vê) ficam como você desenhou.": "instantly, on every connected device. The OBS overlays (the content your audience sees) stay as you designed them.",
    "Contraste reforçado": "Stronger contrast",
    "— textos secundários e bordas deixam de ser suaves; links ganham sublinhado": "— secondary texts and borders stop being soft; links get underlined",
    "Para baixa visão. Combina com o tema ⚡ Alto contraste da aba 🎨 Temas (preto + amarelo), que muda as cores da interface inteira.": "For low vision. Pairs with the ⚡ High contrast theme in the 🎨 Themes tab (black + yellow), which changes the whole interface colors.",
    "Reduzir animações": "Reduce animations",
    "— corta as animações e transições da interface": "— cuts the interface animations and transitions",
    "Para quem tem sensibilidade a movimento (enjoo, epilepsia fotossensível, TDAH). As animações do overlay na live não mudam — elas são parte do seu show.": "For motion sensitivity (nausea, photosensitive epilepsy, ADHD). The overlay animations on stream don’t change — they are part of your show.",
    "Foco visível reforçado": "Strong visible focus",
    "— um anel grosso mostra onde você está ao navegar por Tab": "— a thick ring shows where you are when navigating with Tab",
    "Para quem usa o teclado em vez do mouse (mobilidade reduzida, leitores de tela).": "For keyboard users (reduced mobility, screen readers).",
    "Formas além de cor no status": "Shapes besides color on status",
    "— a bolinha das conexões ganha ✓ (live no ar), ! (sem live) e ✕ (falhou)": "— the connection dot gains ✓ (live on air), ! (no live) and ✕ (failed)",
    "Para daltonismo: verde, amarelo e vermelho deixam de ser a única pista.": "For color blindness: green, yellow and red stop being the only clue.",
    "💡 Também ajudam (já existem em outras abas)": "💡 These also help (they already exist in other tabs)",
    "(no painel) amplia tudo de uma vez; o": "(in the panel) enlarges everything at once; the",
    "Tamanho dos textos": "Text size",
    "e a": "and the",
    "fonte": "font",
    "ficam na aba 🎨 Temas; os avisos importantes aparecem como texto (nunca só como som); e as dicas dos botões são lidas por leitores de tela. Falta algo para você? Conte na aba 📣 Feedback — acessibilidade é prioridade.": "live in the 🎨 Themes tab; important warnings appear as text (never as sound only); and button tips are read by screen readers. Missing something? Tell us in the 📣 Feedback tab — accessibility is a priority.",
    "A conexão falhou": "The connection failed",
    "🎁 Resultado do sorteio": "🎁 Raffle result",
    "O pódio também está na tela do OBS (widget 🎁). Fechar aqui não tira de lá.": "The podium is also on the OBS screen (🎁 widget). Closing here doesn’t remove it there.",
    "Fechar este aviso aqui (a tela do OBS continua como está)": "Close this notice here (the OBS screen stays as it is)",

