    "Tudo apagado: o OBS Social voltou ao padrão de fábrica e vai REINICIAR sozinho em instantes (pelo mesmo caminho da atualização). Esta página recarrega quando ele voltar.": "Everything deleted: OBS Social returned to factory default and will RESTART on its own in moments (through the same path as the update). This page reloads when it comes back.",
