    "Este é o MESMO pódio da tela do OBS (widget 🎁), com o mesmo dado 🎲 e as mesmas configurações — o suspense aqui é o do seu público. Fechar no ✖ acima não tira da tela.": "This is the SAME podium as the OBS screen (🎁 widget), with the same die 🎲 and the same settings — the suspense here is your audience’s. Closing with the ✖ above does not remove it from the screen.",
