    // ---------- v0.46.0: 🎬 OBS pelo painel + 🎵 Mesa de trilhas ----------
    "🎬 OBS Studio pelo painel (experimental)": "🎬 OBS Studio from the panel (experimental)",
    "— trocar cenas, Trocar Tela, silenciar fontes e ver o status da live, direto da ferramenta 🎬 do painel": "— switch scenes, Swap Screen, mute sources and see the live status, right from the panel’s 🎬 tool",
    "Usa o controle remoto que": "Uses the remote control that",
    "já vem no OBS 28+": "ships with OBS 28+",
    ": no OBS, abra": ": in OBS, open",
    "Ferramentas → Configurações do Servidor WebSocket": "Tools → WebSocket Server Settings",
    ", marque": ", check",
    "Ativar servidor WebSocket": "Enable WebSocket server",
    "e copie a senha para cá. A conversa é toda dentro do seu computador — nada passa pela internet.": "and copy the password here. The whole conversation stays inside your computer — nothing goes through the internet.",
    "Porta (a do OBS — padrão 4455)": "Port (the OBS one — default 4455)",
    "Senha do servidor WebSocket": "WebSocket server password",
    "⚪ desligado (ligue o seletor acima)": "⚪ off (turn on the switch above)",
    "A senha fica guardada só neste computador (na pasta": "The password is stored only on this computer (in the",
    ") e nunca é enviada às telas. Quem acessa o painel pela rede só comanda o OBS se você liberar o seletor 🎬 no modo restrito (aba 🔒 Segurança) — de fábrica, fica bloqueado.": ") folder and is never sent to the screens. People opening the panel over the network can only command OBS if you enable the 🎬 selector in restricted mode (🔒 Security tab) — blocked by default.",
    "a que o OBS mostra": "the one OBS shows",
    "Salvar e conectar": "Save and connect",
    "🎵 Mesa de trilhas (experimental)": "🎵 Soundboard (experimental)",
    "— botões de músicas e efeitos no painel; o som toca na live (pelo overlay no OBS), no painel, ou nos dois": "— music and effect buttons on the panel; the sound plays on the live (through the overlay in OBS), on the panel, or both",
    "Cada trilha é um botão na ferramenta 🎵 do painel (e do celular na mesma rede).": "Each track is a button on the panel’s 🎵 tool (and on your phone on the same network).",
    "Uma por vez": "One at a time",
    ": apertar outra troca com fade; BGM pode repetir (🔁); o ⏹ para tudo. Para o som entrar NA LIVE, a fonte do overlay no OBS precisa estar com o áudio ativo (é o normal de uma fonte de navegador).": ": pressing another swaps with a fade; BGM can repeat (🔁); ⏹ stops everything. For the sound to reach THE LIVE, the overlay source in OBS must have audio active (the normal for a browser source).",
    "🎛️ Importar do Stream Deck (backup de perfis)": "🎛️ Import from Stream Deck (profile backup)",
    "No programa Stream Deck:": "In the Stream Deck app:",
    "Preferências → Perfis → exportar backup": "Preferences → Profiles → export backup",
    ". Os botões \"Tocar áudio\" viram trilhas prontas (nome, grupo, volume, 🔁 e fade). Os arquivos de som não vêm no backup — aponte a pasta deles aqui embaixo que eu encontro e copio sozinho.": ". \"Play Audio\" buttons become ready-made tracks (name, group, volume, 🔁 and fade). The audio files don’t come in the backup — point to their folder below and I’ll find and copy them myself.",
    "Enviar um arquivo de som para virar trilha": "Upload a sound file to become a track",
    "Adicionar uma trilha com um som já enviado": "Add a track using an already uploaded sound",
    "Emoji do botão": "Button emoji",
    "Nome da trilha": "Track name",
    "Grupo (pasta)": "Group (folder)",
    "Trilhas do mesmo grupo ficam juntas na mesa": "Tracks in the same group stay together on the board",
    "Cor do botão": "Button color",
    "Remover esta trilha": "Remove this track",
    "O arquivo de som desta trilha (envie novos no campo acima)": "This track’s sound file (upload new ones in the field above)",
    "— escolher o som —": "— choose the sound —",
    "Fade (segundos) na entrada, na troca e no ⏹": "Fade (seconds) on start, on swap and on ⏹",
    "Repetir sem parar (BGM)": "Repeat forever (BGM)",
    "Onde esta trilha toca": "Where this track plays",
    "📡 Na live": "📡 On the live",
    "🖥️ Só no painel": "🖥️ Panel only",
    "📡+🖥️ Nos dois": "📡+🖥️ Both",
    "Procurar os sons das trilhas pendentes nessa pasta": "Look for the pending tracks’ sounds in that folder",
    "Importar do Stream Deck": "Import from Stream Deck",
    "Procurar os sons": "Find the sounds",
    "Escreva o caminho da pasta onde estão os arquivos de som.": "Type the path of the folder where the sound files are.",
    "Esse arquivo é grande demais (limite: 64 MB). Exporte o backup SEM os áudios embutidos — os sons a gente encontra pela pasta.": "That file is too big (limit: 64 MB). Export the backup WITHOUT embedded audio — we find the sounds through the folder.",
    "🎬 Comandar o OBS (cenas, transição, mudo, live/gravação)": "🎬 Command OBS (scenes, transition, mute, live/recording)",
    "Como controlo as cenas do OBS pelo painel?": "How do I control OBS scenes from the panel?",
    "Ligue 🧪 Labs → 🎬 OBS Studio pelo painel (experimental). No OBS, ative Ferramentas → Configurações do Servidor WebSocket e copie a senha para o card do Labs. A ferramenta 🎬 do painel mostra as cenas (no modo estúdio, o clique escolhe o preview e o botão 🎬 manda para o ar), o mudo das fontes e a live/gravação — tudo dentro do seu computador, sem internet.": "Turn on 🧪 Labs → 🎬 OBS Studio from the panel (experimental). In OBS, enable Tools → WebSocket Server Settings and copy the password into the Labs card. The panel’s 🎬 tool shows the scenes (in studio mode, clicking picks the preview and the 🎬 button sends it on air), source mute and live/recording — all inside your computer, no internet.",
    "O que é a 🎵 Mesa de trilhas?": "What is the 🎵 Soundboard?",
    "Uma mesa de som experimental (🧪 Labs): cada trilha vira um botão no painel — e no celular na mesma rede. Uma toca por vez, apertar outra troca com fade, BGM pode repetir (🔁) e o ⏹ para tudo. O som pode sair na live (pelo overlay no OBS), só no painel, ou nos dois. Dá até para importar os botões de som do seu Stream Deck, com um backup de perfis.": "An experimental soundboard (🧪 Labs): each track becomes a button on the panel — and on your phone on the same network. One plays at a time, pressing another swaps with a fade, BGM can repeat (🔁) and ⏹ stops everything. The sound can go to the live (through the overlay in OBS), panel only, or both. You can even import your Stream Deck’s sound buttons from a profile backup.",
    "🎵 Mesa de trilhas": "🎵 Soundboard",
    "🎬 OBS Studio": "🎬 OBS Studio",
    "Mesa de trilhas (Labs)": "Soundboard (Labs)",
    "Parar a trilha (com fade)": "Stop the track (with fade)",
    "A mesa está vazia. As trilhas se cadastram em": "The board is empty. Tracks are set up in",
    "Configurações → 🧪 Labs → 🎵 Mesa de trilhas": "Settings → 🧪 Labs → 🎵 Soundboard",
    "— dá até para importar os botões do seu Stream Deck.": "— you can even import your Stream Deck buttons.",
    "Cada trilha toca onde o destino dela mandar: na live (pelo overlay no OBS), só no painel, ou nos dois. Uma por vez — apertar outra troca com fade.": "Each track plays where its destination says: on the live (through the overlay in OBS), panel only, or both. One at a time — pressing another swaps with a fade.",
