    "uma vez só, o valor que você quiser": "just once, any amount you like",
    "🔁 Apoio mensal": "🔁 Monthly support",
    "renova todo mês, dá para cancelar quando quiser": "renews every month, cancel whenever you want",
    "⚡ Amigos do OBS Social": "⚡ Friends of OBS Social",
    "no LivePix · Pix ou cartão": "on LivePix · Pix or card",
    "💜 assinar": "💜 subscribe",
    "Isto é uma assinatura, diferente das doações de cima: ela se repete todo mês até você cancelar (o cancelamento é na sua conta do LivePix, sem falar com ninguém). Nenhum recurso do programa depende disso — tudo continua grátis para todo mundo, sempre.": "This is a subscription, unlike the donations above: it repeats every month until you cancel (cancelling is done in your own LivePix account, no need to talk to anyone). No feature of the program depends on it — everything stays free for everyone, always.",
    "Aqui fica o ⬅ de voltar quando a pasta está aberta": "This is where the ⬅ back key sits when the folder is open",
