    "Escolha o que esta tecla faz no OBS. As listas de cenas, fontes e filtros vêm do OBS conectado — sem conexão, dá para digitar o nome na mão.": "Pick what this key does in OBS. The lists of scenes, sources and filters come from the connected OBS — with no connection, you can type the name by hand.",
    "🎵 toca um som · 🎬 Ação do OBS: comanda o OBS Studio (gravar, trocar de cena, mudo...) · 🎛️ Botão de multi ação: guarda teclas e o clique toca tudo em fila (segurar abre) · 📁 Pasta simples: só guarda teclas — o clique abre, nada toca": "🎵 plays a sound · 🎬 OBS action: commands OBS Studio (record, switch scene, mute...) · 🎛️ Multi-action button: holds keys and a click plays everything in a queue (hold to open) · 📁 Plain folder: only holds keys — a click opens it, nothing plays",
