    "🎛️ O que aparece no controle do OBS dentro do painel": "🎛️ What shows up in the OBS control inside the panel",
    "Marque só o que você usa. Isso muda a ferramenta 🎬 do painel — as teclas 🎬 da Mesa de Trilhas continuam funcionando de qualquer jeito.": "Tick only what you use. This changes the panel’s 🎬 tool — the 🎬 keys on the Soundboard keep working either way.",
    "📡 Transmitir, ⏺ gravar, ⏸ pausa, 📷 câmera virtual e ⏪ replay": "📡 Stream, ⏺ record, ⏸ pause, 📷 virtual camera and ⏪ replay",
    "🎬 Lista de cenas (clique troca a cena)": "🎬 Scene list (a click switches the scene)",
    "🎭 Modo estúdio, ✨ mandar o preview ao ar e 🔀 transições": "🎭 Studio mode, ✨ send preview on air and 🔀 transitions",
    "👁 Mostrar/esconder as fontes da cena que está no ar": "👁 Show/hide the sources of the scene on air",
    "🔊 Mixer: mudo e volume de cada fonte de áudio": "🔊 Mixer: mute and volume of each audio source",
    "⏯ Controle de mídia (vídeos e playlists do OBS)": "⏯ Media control (OBS videos and playlists)",
    "🎚 Ligar e desligar filtros": "🎚 Enable and disable filters",
    "📸 Print da cena, que cai direto nas mídias do programa": "📸 Screenshot of the scene, landing straight in the app’s media",
    "🗂 Coleções de cenas e 👤 perfis (troca pesada — vem desligado)": "🗂 Scene collections and 👤 profiles (heavy switch — off by default)",
    "— o controle completo do OBS na ferramenta 🎬 do painel: transmitir, gravar (com pausa e marcador de capítulo), câmera virtual, replay, cenas, modo estúdio, transições, mostrar/esconder fontes, mixer de áudio, controle de mídia, filtros, coleções, perfis e print da tela. Tudo isso também vira": "— the complete OBS control in the panel’s 🎬 tool: stream, record (with pause and chapter marker), virtual camera, replay, scenes, studio mode, transitions, show/hide sources, audio mixer, media control, filters, collections, profiles and screenshots. All of it also becomes a",
    "botão na Mesa de Trilhas": "key on the Soundboard",
    "🎬 Comandar o OBS (cenas, live/gravação, mixer, fontes, filtros, mídias — e as teclas 🎬 da Mesa)": "🎬 Command OBS (scenes, stream/recording, mixer, sources, filters, media — and the 🎬 keys on the Soundboard)",
    "Como controlo o OBS pelo painel?": "How do I control OBS from the panel?",
    "Ligue 🧪 Labs → 🎬 OBS Studio pelo painel (experimental). Para linkar: no OBS (28+), abra Ferramentas → Configurações do Servidor WebSocket, marque Ativar servidor WebSocket, clique em Mostrar senha das conexões e copie a porta (4455) e a senha para o card do Labs — o passo a passo numerado está lá. Se o OBS estiver em OUTRO computador da rede, ponha o IP dele no campo Endereço (e libere a porta 4455 no firewall daquela máquina). A ferramenta 🎬 do painel comanda tudo: transmitir, gravar (com pausa e marcador de capítulo), câmera virtual, replay buffer, cenas, modo estúdio, transições, mostrar/esconder fontes, mixer de áudio, controle de mídia, filtros, coleções, perfis e print da tela — e cada bloco tem um liga/desliga no card do Labs, para a ferramenta ficar do tamanho que você usa. Tudo dentro do seu computador, sem internet.": "Turn on 🧪 Labs → 🎬 OBS Studio from the panel (experimental). To link: in OBS (28+), open Tools → WebSocket Server Settings, check Enable WebSocket server, click Show Connect Info and copy the port (4455) and the password into the Labs card — the numbered walkthrough is there. If OBS is on ANOTHER computer on the network, put its IP in the Address field (and open port 4455 on that machine’s firewall). The panel’s 🎬 tool commands everything: stream, record (with pause and chapter marker), virtual camera, replay buffer, scenes, studio mode, transitions, show/hide sources, audio mixer, media control, filters, collections, profiles and screenshots — and each block has an on/off switch on the Labs card, so the tool is only as big as you need. All inside your computer, no internet.",
    "Dá para transformar as coisas do OBS em botões?": "Can I turn OBS things into buttons?",
    "Dá — é a tecla 🎬 Ação do OBS na 🎵 Mesa de trilhas. Crie uma tecla, escolha o tipo 🎬 e depois a ação (trocar de cena, gravar, mudo do microfone, mostrar uma fonte, ligar um filtro, tocar uma mídia...). As listas de cenas, fontes e filtros vêm do OBS conectado; o ▶ Testar agora dispara na hora para você conferir. A tecla acende sozinha quando o que ela controla está ligado (gravando, no ar, fonte visível). Essas teclas também entram dentro de um 🎛️ Botão de multi ação: a fila mistura som e comando — trocar de cena, esperar 2s e tocar a vinheta, por exemplo.": "You can — it’s the 🎬 OBS action key on the 🎵 Soundboard. Create a key, pick type 🎬 and then the action (switch scene, record, mute the microphone, show a source, enable a filter, play a media...). The lists of scenes, sources and filters come from the connected OBS; ▶ Test now fires it immediately so you can check. The key lights up on its own when what it controls is on (recording, live, source visible). These keys also go inside a 🎛️ Multi-action button: the queue mixes sound and command — switch scene, wait 2s and play the sting, for example.",
    // ---------- v0.53: rótulos curtos do editor da tecla 🎬 ----------
