    // ---------- v0.53: recados do controlador do OBS ----------
    "o OBS não está conectado — confira o card 🎬 em Configurações → 🧪 Labs": "OBS is not connected — check the 🎬 card in Settings → 🧪 Labs",
    "espere alguns segundos entre um print e outro": "wait a few seconds between one screenshot and the next",
    "não consegui salvar o print (veja a janela preta do programa)": "couldn’t save the screenshot (see the app’s black window)",
    "o OBS não conseguiu salvar o replay": "OBS could not save the replay",
