    "Dá para transformar as coisas do vMix em botões?": "Can vMix things become buttons?",
    "🕒 tempo de membro (YouTube)": "🕒 membership time (YouTube)",
    "meses de membro": "months as a member",
    "Meses como membro (0 = membro novo). O YouTube troca o selo em 1, 2, 6, 12, 24, 36... meses.": "Months as a member (0 = new member). YouTube changes the badge at 1, 2, 6, 12, 24, 36... months.",
    "🎯 Faixas — por 💰 valor, 🎨 cor do Super Chat, 🔤 palavra no nome ou 🕒 tempo de membro": "🎯 Brackets — by 💰 amount, 🎨 Super Chat color, 🔤 word in the name or 🕒 membership time",
    "Cada faixa escolhe COMO casar: 💰 a partir de um valor em reais (Super Chat, 🎟️ Super Sticker e 💝 doação, qualquer moeda); 🎨 pelo tom que o próprio YouTube pintou no Super Chat ou no Super Sticker; 🔤 por uma palavra que aparece no espaço do nome (o nome, «Membro», o nível do canal...); ou 🕒 a partir de tantos meses como membro do YouTube (o tempo que o selo do membro mostra: novo, 1, 2, 6, 12, 24 meses...). Quando mais de uma serve, a ordem é: cor → valor → palavra → tempo de membro → comentário comum.": "Each bracket chooses HOW to match: 💰 from an amount in reais up (Super Chat, 🎟️ Super Sticker and 💝 donation, any currency); 🎨 by the tone YouTube itself painted on the Super Chat or Super Sticker; 🔤 by a word that shows in the name area (the name, «Member», the channel level...); or 🕒 from so many months as a YouTube member (the time the member badge shows: new, 1, 2, 6, 12, 24 months...). When more than one fits, the order is: color → amount → word → membership time → regular comment.",
    "🔑 Palavras para participar (até 30)": "🔑 Words to enter (up to 30)",
    "Com palavras na lista, só entra no sorteio quem digitar uma delas no chat. Lista vazia: todo mundo que fala entra.": "With words on the list, only those who type one of them in chat enter the raffle. Empty list: everyone who talks enters.",
    "Com palavras na lista, só entra quem digitar": "With words on the list, only those who type",
    "uma delas": "one of them",
    "no chat — a palavra inteira, sem diferença entre maiúsculas e minúsculas («#sorteio» vale como «sorteio»). Lista vazia = todo mundo que fala entra, como sempre.": "in chat enter — the whole word, case-insensitive (\"#raffle\" counts as \"raffle\"). Empty list = everyone who talks enters, as always.",
    "ex.: sorteio": "e.g. raffle",
    "Nova palavra do sorteio": "New raffle word",
    "Adicionar esta palavra": "Add this word",
    "Tirar esta palavra": "Remove this word",
    "Nenhuma palavra — todo mundo que fala no chat entra.": "No words — everyone who talks in chat enters.",
    "limite de 30 palavras": "30-word limit",
    "Voltar (desfaz o último ajuste do sorteio — vale também para o que foi mexido no botão 🎁 do painel)": "Back (undoes the last raffle change — also what was changed in the 🎁 button of the dashboard)",
    "TUDO do sorteio de volta ao padrão: palavras, fichas, dado, som e resposta (dá para desfazer)": "EVERYTHING in the raffle back to default: words, tokens, dice, sound and reply (can be undone)",
    "📏 Pontilhado do modo medida": "📏 Measure-mode dotted line",
    "Quanto o contorno pontilhado branco aparece enquanto você digita no seletor manual (modo medida). Preferência deste navegador.": "How strongly the white dotted outline shows while you type in the manual sizer (measure mode). Preference of this browser.",
    "Mais visível": "More visible",
    "Bem visível": "Very visible",
    "📺 Por rede — cada uma pode vestir o seu próprio molde de comentário comum": "📺 Per network — each one can wear its own regular-comment profile",
    "Um molde marcado como exclusivo de uma rede (▶️ 💜 🟢 💙) nunca veste comentário de outra. Aqui você diz o que cada rede veste quando nenhuma faixa casa: o comum acima, um molde só dela ou o visual ao vivo (sem molde).": "A profile marked as exclusive to one network (▶️ 💜 🟢 💙) never wears a comment from another. Here you say what each network wears when no tier matches: the regular one above, a profile of its own or the live look (no profile).",
    "💰 Super Chat ou doação que não casa com faixa nenhuma veste": "💰 Super Chat or donation matching no tier wears",
    "— o mesmo do comentário comum —": "— same as the regular comment —",
    "— o visual ao vivo (sem molde) —": "— the live look (no profile) —",
    "— o mesmo do comentário comum da rede —": "— same as the network's regular comment —",
    "⚠️ O visual ao vivo (quem veste tudo que não casa com molde) está com a arte «{arte}». Se a ideia era a arte só nos moldes, tire-a do visual ao vivo:": "⚠️ The live look (which wears everything that matches no profile) carries the artwork \"{arte}\". If the artwork was meant for the profiles only, remove it from the live look:",
    "🎭 Editando:": "🎭 Editing:",
    "Qual visual do destaque esta aba ajusta: o visual ao vivo (sem molde) ou um molde salvo. É o mesmo seletor 🎭 Editando do 🖱️ Organizar a tela.": "Which highlight look this tab adjusts: the live look (no profile) or a saved profile. It is the same 🎭 Editing selector as in 🖱️ Arrange the screen.",
    "⚠️ O comentário no ar está vestindo o molde «{molde}» pelo 🎭 automático — o que você ajusta aqui vai para o visual ao vivo, que a tela NÃO está mostrando agora. Abra o molde para mudar o que está na tela.": "⚠️ The comment on air is wearing the \"{molde}\" profile via 🎭 automatic — what you adjust here goes to the live look, which the screen is NOT showing right now. Open the profile to change what is on screen.",
    "⚠️ O comentário no ar está vestindo o molde «{molde}» pelo 🎭 automático — você está ajustando «{editando}». Abra «{molde}» para mudar o que está na tela.": "⚠️ The comment on air is wearing the \"{molde}\" profile via 🎭 automatic — you are adjusting \"{editando}\". Open \"{molde}\" to change what is on screen.",
    "🎭 Abrir «{molde}»": "🎭 Open \"{molde}\"",
