    "Vale com o widget nos presets de sempre ou solto em peças — é a mesma formatação da linha ✍️ do 🖱️ Organizar a tela.": "Applies with the widget in its usual presets or loose in pieces — it is the same formatting as the ✍️ row in 🖱️ Arrange the screen.",
    "Cada texto do chat tem a sua formatação: o nome de quem comenta e o texto do comentário.": "Each chat text has its own formatting: the commenter's name and the comment text.",
