    "✍️ Formatação da letra: clique numa peça com texto (nome, texto, valor, títulos, números...) e os ajustes de fonte, negrito, contorno... aparecem aqui.": "✍️ Letter formatting: click a piece with text (name, text, amount, titles, numbers...) and the font, bold, outline... controls show up here.",
    "✍️ «{peca}» é imagem ou caixa, não tem letra para formatar — clique numa peça com texto (nome, texto, valor, títulos, números...).": "✍️ \"{peca}\" is an image or a box, it has no letters to format — click a piece with text (name, text, amount, titles, numbers...).",
