    "Na live, este comentário vestiria o molde": "On the live, this comment would wear the profile",
    "A prévia mostra o visual ao vivo, que é o que você está editando — para ajustar o molde, abra-o no seletor 🎭 Editando.": "The preview shows the live look, which is what you are editing — to adjust the profile, open it in the 🎭 Editing selector.",
