    "Joga fora o que você mexeu neste molde e volta à última foto dele (de quando você entrou, ou do último 💾)": "Throws away what you changed in this template and goes back to its last snapshot (from when you entered it, or the last 💾)",
    "O comentário em destaque volta ao padrão do programa: sem arte, montagem normal, posição e tamanho de sempre (os perfis salvos não mudam)": "The featured comment goes back to the program default: no artwork, normal assembly, usual position and size (saved profiles do not change)",
    "Jogar fora o que você mexeu neste molde e voltar à última foto dele (de quando você entrou, ou do último 💾)?": "Throw away what you changed in this template and go back to its last snapshot (from when you entered it, or the last 💾)?",
    "O comentário em destaque volta ao PADRÃO do programa: sem arte, montagem normal, posição e tamanho de sempre. Os perfis salvos não mudam. (Dá para desfazer no ◀ do Organizar.)": "The featured comment goes back to the program DEFAULT: no artwork, normal assembly, usual position and size. Saved profiles do not change. (Undo with the ◀ of Arrange.)",
