    "e só vai para a tela quando você mandar (botão direito → 📺); nomes que parecem telefone continuam mascarados na tela, como sempre. Uma opção por biblioteca aberta rodando no seu computador (sem gateway e sem mensalidade — mesmo risco) está a caminho.": "folder and only reaches the screen when you send it (right-click → 📺); names that look like phone numbers stay masked on screen, as always. An open-source library option running on your computer (no gateway, no subscription — same risk) is on the way.",
