    "e só vai para a tela quando você mandar (botão direito → 📺); nomes que parecem telefone continuam mascarados na tela, como sempre. Dá para escolher entre DOIS modos no card de Conexões: o gateway Whapi (pago) ou a biblioteca aberta rodando no seu computador (grátis, QR — mesmo risco).": "folder and only reaches the screen when you send it (right-click → 📺); names that look like phone numbers stay masked on screen, as always. You can choose between TWO modes on the Connections card: the Whapi gateway (paid) or the open library running on your computer (free, QR — same risk).",
