    "🔎 Filtrar nesta pasta": "🔎 Filter in this folder",
    "Mostra só as pastas e mídias cujo nome tem o que você digitar": "Shows only the folders and media whose name contains what you type",
    "O que esta pasta tem": "What this folder has",
    "Nada com esse nome nesta pasta.": "Nothing with that name in this folder.",
    "Nenhuma imagem, vídeo ou áudio nesta pasta — abra uma das pastas acima.": "No image, video or audio in this folder — open one of the folders above.",
    "Nenhuma imagem, vídeo ou áudio nesta pasta.": "No image, video or audio in this folder.",
    "📂 Arquivos do computador só podem ser escolhidos no painel aberto no próprio computador do streamer — pela rede, use uma URL.": "📂 Files from the computer can only be picked on the panel opened on the streamer’s own computer — over the network, use a URL.",
    "Tirar a mídia da tela e esquecer o item": "Take the media off the screen and forget the item",
    "A prévia aqui no painel nasce muda para o som não dobrar com a cena do OBS — marque para ouvir neste navegador": "The preview here on the panel starts muted so the sound doesn’t double with the OBS scene — check to hear it in this browser",
    "🔈 ouvir aqui": "🔈 listen here",
    "Quando acabar, recomeça sozinha na tela do público": "When it ends, it restarts on its own on the public screen",
    "🔁 Repetir": "🔁 Repeat",
    "▶️ O player é do próprio site — daqui dá só para mostrar/tirar, tamanho e tela cheia.": "▶️ The player belongs to the site itself — from here you can only show/remove, size and full screen.",
    "Cole uma URL (YouTube, TikTok, Instagram, X, Vimeo, clipe da Twitch, anexo do Discord ou o link direto de um arquivo) ou aponte um arquivo do seu computador. Nada é enviado para a biblioteca de mídias. O público vê na cena do OBS (overlay); a prévia aqui é só para você acompanhar.": "Paste a URL (YouTube, TikTok, Instagram, X, Vimeo, Twitch clip, Discord attachment or the direct link to a file) or point to a file on your computer. Nothing is sent to the media library. The audience sees it in the OBS scene (overlay); the preview here is just for you to follow along.",
    "na tela": "on screen",
